import React, { useState } from "react";
import {
  BrowserRouter as Router,
  Routes,
  Route,
} from "react-router-dom";
import Login from "./Login";
import AdminDashboard from "./AdminDashboard";
import UserShop from "./components/UserShop";
import CartPage from "./components/CartPage";
import CheckoutPage from "./components/CheckoutPage";
import OrderSuccess from "./components/OrderSuccess";

function App() {
  const [role, setRole] = useState(null);
  const [token, setToken] = useState(null);
  const [message, setMessage] = useState("");
  const [page, setPage] = useState("home"); // 👈 track which page: home, login, register

  // ✅ Login handler
  const handleLogin = (username, password, type) => {
    if (type === "admin" && username === "admin" && password === "pass") {
      setRole("admin");
      setToken("admin_token");
      setMessage("✅ Admin login successful!");
      setPage("dashboard");
    } else if (type === "user") {
      setRole("user");
      setToken("user_token");
      setMessage(`👤 Welcome, ${username}!`);
      setPage("dashboard");
    } else {
      setMessage("❌ Invalid credentials");
    }
  };

  // ✅ Logout handler
  const handleLogout = () => {
    setRole(null);
    setToken(null);
    setMessage("You have logged out.");
    setPage("home");
  };

  return (
    <Router>
      <div className="min-h-screen font-sans">
        {/* ✅ Show navbar ONLY on home page */}
        {page === "home" && (
          <nav className="flex justify-between px-6 py-4 bg-gray-900 text-white fixed top-0 w-full shadow-md z-50">
            <h1 className="text-2xl font-bold">💊 MediShop</h1>
            <div className="space-x-4">
              <button
                onClick={() => setPage("login")}
                className="hover:text-indigo-400"
              >
                Login
              </button>
              <button
                onClick={() => setPage("register")}
                className="hover:text-indigo-400"
              >
                Register
              </button>
            </div>
          </nav>
        )}

        {/* ✅ Show background only on home page */}
        {page === "home" && (
          <div
            className="flex flex-col justify-center items-center text-center h-screen bg-cover bg-center"
            style={{
              backgroundImage: "url('/medical.jpg')",
            }}
          >
            <div className="bg-black/50 p-10 rounded-xl text-white backdrop-blur-sm">
              <h2 className="text-3xl font-bold mb-4">
                Welcome to 💊 MediShop
              </h2>
              <p className="text-lg">
                Your trusted online medicine store — order easily from home.
              </p>
            </div>
          </div>
        )}

        {/* ✅ Login Page (No navbar or background) */}
        {page === "login" && !role && (
          <Login onLogin={handleLogin} message={{ type: "", text: message }} />
        )}

        {/* ✅ Register Page */}
        {page === "register" && !role && (
          <div className="flex justify-center items-center min-h-screen bg-gray-100 text-gray-700 text-lg">
           <Register onLogin={handleLogin} message={{type: "", text:message}} />
            {/* Registration page under development...
            <button
              onClick={() => setPage("home")}
              className="ml-4 text-indigo-600 underline"
            >
              Back to Home
            </button> */}
          </div>
        )}

        {/* ✅ After Login */}
        {role === "admin" && page === "dashboard" && (
          <AdminDashboard
            token={token}
            onLogout={handleLogout}
            setMessage={setMessage}
          />
        )}

        {role === "user" && page === "dashboard" && (
          <Routes>
            <Route
              path="/"
              element={
                <UserShop
                  token={token}
                  onLogout={handleLogout}
                  setMessage={setMessage}
                />
              }
            />
            <Route path="/cart" element={<CartPage />} />
            <Route path="/checkout" element={<CheckoutPage />} />
            <Route path="/success" element={<OrderSuccess />} />
          </Routes>
        )}
      </div>
    </Router>
  );
}

export default App;
